css:
/* Import Overpass Mono from Google Fonts */
@import url("s://fonts.googleapis.com/css2?family=Overpass+Mono:wght@400;700&display=swap");

.input-color-group-one {
  position: relative;
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.input-color {
  max-width: 230px;
  min-width: 150px;
  border: 2px solid var(--color-border);
  border-radius: 0px;
  background: var(--color-bg);
  color: var(--color-input);
  padding: 16px;
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.input-color:focus {
  color: var(--color-input);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.input-color:valid {
  color: var(--color-input);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.input-color:placeholder {
  color: var(--color-border);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.color-label {
  position: absolute;
  display: flex;
  justify-content: center;
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}
.input-color {
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.info-panels {
  --color-icon: solid var;
  --color-input: #000000;
  --color-border: #1648c7;
  --color-border-hover: 2px solid var;
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 700;
}

.input-color {
  max-width: 230px;
  min-width: 150px;
  border: 2px solid var(--color-border);
  border-radius: 0px;
  background: #fff;
  font-size: 12px;
  text-align: center;
}

.input-color:focus {
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  color: var(--color-input);
}

.input-color:valid {
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  color: var(--color-input);
}

.input-color:-webkit-input-placeholder {
  color: var(--color-input);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */

  font-size: 12px;
}

.input-color:-moz-input-placeholder {
  color: var(--color-input);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
}

.input-color::-ms-input-placeholder {
  color: var(--color-input);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
}

.input-color:focus::-webkit-input-placeholder,
.input-color:valid::-webkit-input-placeholder {
  opacity: var(--input-focus-opacity);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
}

.input-color:focus::-moz-input-placeholder,
.input-color:valid::-moz-input-placeholder {
  opacity: var(--input-focus-opacity);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
}

.input-color:focus::-ms-input-placeholder,
.input-color:valid::-ms-input-placeholder {
  opacity: var(--input-focus-opacity);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
}

.color-label {
  position: absolute;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  color: var(--color-border);
  font-family: "Overpass Mono", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em; /* minimal spacing */
  font-size: 12px;
  font-weight: 600;
  background-color: #fff;
  padding: 0 5px;
  border: 2px solid var(--color-border);
  border-radius: 0px;
  top: -11.5px;
  left: 25px;
  cursor: crosshair;
  backdrop-filter: blur(10px);
}

.btn-copy {
  position: absolute;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 24px;
  height: 24px;
  border: 2px solid var(--color-border);
  border-radius: 50px;
  top: -11.5px;
  right: 25px;
  background-color: #fff;
  cursor: crosshair;
  backdrop-filter: blur(10px);
  transition: var(--all-transition);
}

.btn-copy:hover {
  background-color: var(--color-border);
  transform: scale(1.1);
}

.btn-copy:active {
  transform: scale(1.1);
}

.input-color:focus ~ .btn-copy {
  border: 2px solid var(--color-border);
}

.input-color:valid .input-color:focus ~ .btn-copy {
  border: 2px solid var(--color-border);
}

.input-color:focus ~ .btn-copy:hover {
  background-color: var(--color-border-hover);
}

#icon-btn-copy {
  fill: var(--color-border);
}

.btn-copy:hover #icon-btn-copy {
  fill: var(--color-icon);
}

.input-color:focus ~ .btn-copy #icon-btn-copy {
  fill: var(--color-border-hover);
}

.input-color:focus ~ .btn-copy:hover #icon-btn-copy,
.input-color:valid ~ .btn-copy:hover #icon-btn-copy {
  fill: var(--color-icon);
}
